<script setup>
import { onMounted,ref } from 'vue'
import { api } from '../api'
import {labelOf} from '../ui'
import EvidenceText from '../components/EvidenceText.vue'
import RetrievalDetails from '../components/RetrievalDetails.vue'
import {embeddingLabel,rerankLabel} from '../retrieval'
const query=ref('混合检索'),mode=ref('hybrid'),kbs=ref([]),selected=ref([]),rerank=ref(true),data=ref(null),loading=ref(false),error=ref('')
onMounted(async()=>{try{const [bases,state]=await Promise.all([api('/api/knowledge-bases'),api('/api/model-status')]);kbs.value=bases;mode.value=state.retrieval.mode;rerank.value=state.retrieval.rerank}catch(e){error.value=e.message}})
async function run(){loading.value=true;error.value='';try{data.value=await api('/api/search',{method:'POST',body:JSON.stringify({query:query.value,mode:mode.value,knowledge_base_ids:selected.value,rerank:rerank.value})})}catch(e){error.value=e.message}finally{loading.value=false}}
</script>
<template><div class="page-stack"><div class="page-intro"><div><h2>检索测试台</h2><p>片段级召回与引用定位，权限过滤在服务端执行</p></div></div><form class="card search-console" @submit.prevent="run"><div class="search-row"><input v-model="query" aria-label="检索测试问题" class="input" placeholder="输入测试问题或关键字" required/><button class="primary-button" :disabled="loading">{{loading?'检索中…':'开始检索'}}</button></div><div class="toolbar"><label v-for="item in [{k:'vector',n:'向量检索'},{k:'keyword',n:'关键字检索（BM25）'},{k:'hybrid',n:'混合检索（RRF）'}]" :key="item.k"><input v-model="mode" type="radio" :value="item.k"/>{{item.n}}</label></div><details class="search-options"><summary>知识范围与重排设置 · {{selected.length?'已选 '+selected.length+' 个知识库':'全部授权知识库'}}</summary><div class="toolbar"><label v-for="kb in kbs" :key="kb.id"><input v-model="selected" type="checkbox" :value="kb.id"/>{{kb.name}}</label><small>未选时搜索全部授权知识库</small><label><input v-model="rerank" type="checkbox"/>启用重排（按系统配置）</label></div></details></form><div v-if="error" class="error-banner">{{error}}</div><div v-if="data" class="card"><div class="card-header"><div><h3>检索结果</h3><p>{{data.total}} 条 · {{data.elapsed_ms}} ms · {{labelOf(data.mode)}} · 向量：{{embeddingLabel(data.pipeline.embedding)}} · 重排：{{rerankLabel(data.pipeline.rerank)}}</p></div></div><div class="card-body"><RetrievalDetails :pipeline="data.pipeline"/><article v-for="item in data.results" :key="item.chunk_id" class="search-result"><div class="result-head"><router-link :to="{path:`/documents/${item.document_id}`,query:{chunk:item.chunk_id}}">{{item.name}} · {{item.version}}</router-link><span class="result-score">相关度 {{item.relevance}}</span></div><EvidenceText :content="item.snippet" :citations="[item]"/></article><div v-if="!data.total" class="empty">没有找到足够相关的可用片段</div></div></div></div></template>
<style scoped>.search-options{font-size:12px;color:var(--muted)}.search-options summary{cursor:pointer}.search-options .toolbar{margin-top:14px}.search-row button{flex-shrink:0}.result-head{flex-wrap:wrap}.result-score{white-space:nowrap}@media(max-width:450px){.search-console{padding:16px}.search-row{flex-direction:column}.search-console>.toolbar{align-items:flex-start;flex-direction:column;gap:12px}}.search-console{padding:22px;display:grid;gap:18px}.search-row{display:flex;gap:12px}.search-row input{flex:1;min-width:0}.search-console label{font-size:13px}.search-console small{color:#657a88}.result-head a{color:#24638f;font-weight:700}</style>
